<script setup>import { reactive, ref } from "vue"; import { authService } from "../../services/api"; import AuthLayout from "../../layouts/AuthLayout.vue"; const form = reactive({ nom_complet: "", email: "", departement: "", poste: "", mot_de_passe: "", confirmation: "" }); const error = ref(""); const done = ref(false); const submit = async () => { error.value = ""; if (form.mot_de_passe !== form.confirmation) { error.value = "Les mots de passe ne correspondent pas."; return; } try { const { confirmation, ...payload } = form; await authService.register(payload); done.value = true; } catch (exception) { error.value = exception.message; } };</script><template><AuthLayout><h1 class="mt-8 text-3xl font-bold text-slate-800">Créer un compte</h1><div v-if="done" class="mt-6 alert alert-success">Votre compte est en attente de validation par un administrateur.</div><form v-else class="mt-6 grid gap-3" @submit.prevent="submit"><input v-model="form.nom_complet" class="input input-bordered" placeholder="Nom complet" required><input v-model="form.email" type="email" class="input input-bordered" placeholder="Adresse e-mail" required><input v-model="form.departement" class="input input-bordered" placeholder="Département" required><input v-model="form.poste" class="input input-bordered" placeholder="Poste" required><input v-model="form.mot_de_passe" type="password" class="input input-bordered" placeholder="Mot de passe" required><input v-model="form.confirmation" type="password" class="input input-bordered" placeholder="Confirmation du mot de passe" required><p v-if="error" class="text-sm text-error">{{ error }}</p><button class="btn border-0 bg-[#17482d] text-white">Créer mon compte</button></form><p class="mt-6 text-center text-sm"><RouterLink class="font-semibold text-[#17482d]" to="/login">Retour à la connexion</RouterLink></p></AuthLayout></template>
